-- ============================================================
-- 50-dados-sim-sinasc-2019-2024.sql (Gauntlet P3 · caso de teste #1)
-- Snapshot oficial de dado ABERTO coletado do TabNet/DATASUS em 2026-08-26
-- (padrão db/42: Fonte/Carga com sha256 REAL do bruto; idempotente; nada de
-- usuários/tokens/eventos privados). Brutos da coleta ficam fora do repositório;
-- cada "Carga" abaixo guarda o hash do CSV tal como o TabNet o serviu.
--
-- O QUE ENTRA:
-- - "Óbitos infantis" (SOMA) e "Nascidos vivos" (SOMA): município × ano,
--   2019–2024 (dados FINAIS até 2024, atualizados em 02/12/2025 na fonte).
-- - "Taxa de mortalidade infantil" (RECALCULO Σóbitos/Σnascidos, FatorEscala
--   1000 — POR MIL nascidos vivos, db/49). Os TRÊS nascem EM_ANALISE:
--   publicar é parecer humano (RG-09), nunca deste arquivo.
-- - "ObservacaoCausa": decomposição dos óbitos infantis por
--   CAPITULO_CID10 e COMPONENTE etário (todos os municípios com óbito +
--   recorte estadual, ano a ano) e por CAUSA_EVITAVEL (lista "causas
--   evitáveis 0 a 4 anos" — recorte estadual + os 20 maiores municípios por
--   nascidos vivos). CORTE DOCUMENTADO: o cubo do TabNet só publica a
--   dimensão de causas evitáveis como LINHA da tabulação (não como coluna),
--   então cada recorte municipal é uma tabulação própria; limitamos aos 20
--   maiores (custo/benefício declarado no gauntlet). Guardamos os GRUPOS da
--   lista (1.1–1.4, 2, 3) — as folhas ".." somariam em dobro.
--
-- SEMÂNTICA DE ZERO × AUSÊNCIA (rodada 2 do gauntlet — veredito do crítico
-- de dados, que provou na API viva que a vigência "≤ referência" aplicada a
-- dado de EVENTO fabricava taxas com parcelas de anos diferentes: Sinop
-- "8,7" falso = óbitos 2023 ÷ nascidos 2024, verdadeiro 13,5; TMI estadual
-- +8,5% numa malha completa; municípios sem óbito sumindo do ranking):
-- - Óbitos infantis e nascidos vivos são dados de EVENTO (contagem anual),
--   não de estoque. Nas duas tabulações ESTADUAIS COMPLETAS (óbitos por
--   município×ano; nascidos por município×ano), o TabNet/SIM/SINASC lista
--   todo município com ao menos um evento no período — logo, célula "-" ou
--   linha ausente significa ZERO EVENTOS NAQUELE ANO (evento raro que não
--   ocorreu), não dado faltante. Epidemiologia básica do SIM: um município
--   pequeno passar um ano sem óbito infantil é um RESULTADO (o melhor
--   possível), e omiti-lo faria o motor herdar o último ano com morte —
--   imputação silenciosa do passado, que RN-005 proíbe. Por isso este
--   arquivo MATERIALIZA Valor 0 para cada par (município da malha × ano
--   2019–2024) sem linha na tabulação completa — malha-relativo
--   (INSERT ... SELECT ... JOIN "Municipio" WHERE NOT EXISTS), funciona em
--   qualquer banco, e idempotente (reaplicar não duplica).
-- - A materialização vale SOMENTE para as tabulações estaduais completas.
--   Nas tabulações PARCIAIS (causas evitáveis municipais, coletadas apenas
--   para os 20 maiores municípios por nascidos vivos), a ausência de um
--   município continua sendo AUSÊNCIA DE COLETA (aquele recorte não foi
--   tabulado) — nunca vira zero (RN-005).
-- - Consequência aritmética: nascidos = 0 com óbitos = 0 (possível em
--   município minúsculo) dá taxa incalculável (denominador 0) — o motor
--   responde ausência com motivo, sem imputar.
--
-- QUALIDADE (regras aplicadas na geração, com conferência dura):
-- - "Município ignorado - MT" e rodapés ficam fora; Σ municípios ==
--   Total oficial da tabulação conferido por ano (óbitos), e Σ categorias ==
--   total do território conferido linha a linha (capítulo/componente/evitáveis).
-- - Municípios resolvidos por código IBGE de 6 dígitos contra a malha
--   ("Municipio", left 6) — linha sem malha não entra (sem imputação).
-- - "ObservacaoCausa_CodigoIbge" NULL = recorte estadual oficial da fonte.
-- ============================================================

INSERT INTO "Fonte" ("Fonte_Nome","Fonte_Origem","Fonte_Url","Fonte_BaseLegal","Fonte_Licenca","Fonte_Periodicidade","Fonte_VigenciaInicio","Fonte_VigenciaFim")
VALUES ('SIM/DATASUS — Óbitos infantis (TabNet, inf10mt)','Ministério da Saúde — SVSA/CGIAE — Sistema de Informações sobre Mortalidade (SIM)','http://tabnet.datasus.gov.br/cgi/deftohtm.exe?sim/cnv/inf10mt.def','DADO_ABERTO','Informações de Saúde — DATASUS (Lei 12.527/2011)','ANUAL',NULL,NULL)
