INSERT INTO "SubtemaConsulta" ("SubtemaConsulta_TemaId","SubtemaConsulta_Nome","SubtemaConsulta_Status")
SELECT t."TemaConsulta_Id",'Mortalidade infantil','SEM_FONTE'
FROM "TemaConsulta" t WHERE t."TemaConsulta_Nome"='Saúde'
  AND NOT EXISTS (SELECT 1 FROM "SubtemaConsulta" s WHERE s."SubtemaConsulta_TemaId"=t."TemaConsulta_Id" AND s."SubtemaConsulta_Nome"='Mortalidade infantil');

INSERT INTO "Indicador" ("Indicador_SubtemaId","Indicador_Nome","Indicador_Unidade","Indicador_TipoAgregacao","Indicador_MetodologiaUrl","Indicador_StatusValidacao")
SELECT s."SubtemaConsulta_Id",'Óbitos infantis','óbitos','SOMA',NULL,'EM_ANALISE'
FROM "SubtemaConsulta" s JOIN "TemaConsulta" t ON t."TemaConsulta_Id"=s."SubtemaConsulta_TemaId"
WHERE t."TemaConsulta_Nome"='Saúde' AND s."SubtemaConsulta_Nome"='Mortalidade infantil'
  AND NOT EXISTS (SELECT 1 FROM "Indicador" existente WHERE existente."Indicador_Nome"='Óbitos infantis');

INSERT INTO "Indicador" ("Indicador_SubtemaId","Indicador_Nome","Indicador_Unidade","Indicador_TipoAgregacao","Indicador_MetodologiaUrl","Indicador_StatusValidacao")
SELECT s."SubtemaConsulta_Id",'Nascidos vivos','nascidos vivos','SOMA',NULL,'EM_ANALISE'
FROM "SubtemaConsulta" s JOIN "TemaConsulta" t ON t."TemaConsulta_Id"=s."SubtemaConsulta_TemaId"
WHERE t."TemaConsulta_Nome"='Saúde' AND s."SubtemaConsulta_Nome"='Mortalidade infantil'
  AND NOT EXISTS (SELECT 1 FROM "Indicador" existente WHERE existente."Indicador_Nome"='Nascidos vivos');

-- Taxa POR MIL: o FatorEscala 1000 (db/49) substitui o ×100 fixo do RECALCULO
INSERT INTO "Indicador" ("Indicador_SubtemaId","Indicador_Nome","Indicador_Unidade","Indicador_TipoAgregacao","Indicador_NumeradorId","Indicador_DenominadorId","Indicador_FatorEscala","Indicador_MetodologiaUrl","Indicador_StatusValidacao")
SELECT s."SubtemaConsulta_Id",'Taxa de mortalidade infantil','por mil nascidos vivos','RECALCULO',
       (SELECT "Indicador_Id" FROM "Indicador" WHERE "Indicador_Nome"='Óbitos infantis'),
       (SELECT "Indicador_Id" FROM "Indicador" WHERE "Indicador_Nome"='Nascidos vivos'),
       1000,NULL,'EM_ANALISE'
FROM "SubtemaConsulta" s JOIN "TemaConsulta" t ON t."TemaConsulta_Id"=s."SubtemaConsulta_TemaId"
WHERE t."TemaConsulta_Nome"='Saúde' AND s."SubtemaConsulta_Nome"='Mortalidade infantil'
  AND NOT EXISTS (SELECT 1 FROM "Indicador" existente WHERE existente."Indicador_Nome"='Taxa de mortalidade infantil');

