INSERT INTO "Observacao" ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_Valor","Observacao_FonteId","Observacao_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(d.ano,12,31), d.valor, carga.fonte_id, carga.id
FROM dados d
JOIN "Municipio" m ON left(m."Municipio_CodigoIbge",6)=d.cod6
CROSS JOIN carga CROSS JOIN ind
ON CONFLICT ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_FonteId")
DO UPDATE SET "Observacao_Valor"=EXCLUDED."Observacao_Valor", "Observacao_CargaId"=EXCLUDED."Observacao_CargaId";

-- Nascidos vivos por município × ano (tabulação estadual COMPLETA)

WITH carga AS (
  SELECT c."Carga_Id" id, c."Carga_FonteId" fonte_id FROM "Carga" c
  JOIN "Fonte" f ON f."Fonte_Id"=c."Carga_FonteId"
  WHERE f."Fonte_Nome"='SINASC/DATASUS — Nascidos vivos (TabNet, nvmt)' AND c."Carga_HashSha256"='bb76f145b8262d7d871c809bb966add4591dfa023dfd9d205fbb4385006fc8a9'
), ind AS (SELECT "Indicador_Id" id FROM "Indicador" WHERE "Indicador_Nome"='Nascidos vivos'),
dados(cod6,ano,valor) AS (VALUES
