INSERT INTO "Observacao" ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_Valor","Observacao_FonteId","Observacao_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(d.ano,12,31), d.valor, carga.fonte_id, carga.id
FROM dados d
JOIN "Municipio" m ON left(m."Municipio_CodigoIbge",6)=d.cod6
CROSS JOIN carga CROSS JOIN ind
ON CONFLICT ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_FonteId")
DO UPDATE SET "Observacao_Valor"=EXCLUDED."Observacao_Valor", "Observacao_CargaId"=EXCLUDED."Observacao_CargaId";

-- ZEROS: municípios da malha sem óbito infantil no ano (2019–2024)
-- Dado de EVENTO: ausência na tabulação estadual COMPLETA = 0 eventos no ano
-- (ver cabeçalho, "SEMÂNTICA DE ZERO × AUSÊNCIA"). A carga referenciada é a
-- da própria tabulação completa — é ELA que afirma o zero por omissão.
WITH carga AS (
  SELECT c."Carga_Id" id, c."Carga_FonteId" fonte_id FROM "Carga" c
  JOIN "Fonte" f ON f."Fonte_Id"=c."Carga_FonteId"
  WHERE f."Fonte_Nome"='SIM/DATASUS — Óbitos infantis (TabNet, inf10mt)' AND c."Carga_HashSha256"='2d3961a93b470f991011fa8f363058e7bae618467a340a520007832c2767e37f'
), ind AS (SELECT "Indicador_Id" id FROM "Indicador" WHERE "Indicador_Nome"='Óbitos infantis'),
anos(ano) AS (VALUES (2019),(2020),(2021),(2022),(2023),(2024))
INSERT INTO "Observacao" ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_Valor","Observacao_FonteId","Observacao_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(anos.ano,12,31), 0, carga.fonte_id, carga.id
FROM "Municipio" m
CROSS JOIN anos CROSS JOIN carga CROSS JOIN ind
WHERE NOT EXISTS (
  SELECT 1 FROM "Observacao" o
   WHERE o."Observacao_IndicadorId"=ind.id
     AND o."Observacao_CodigoIbge"=m."Municipio_CodigoIbge"
     AND o."Observacao_DataReferencia"=make_date(anos.ano,12,31))
ON CONFLICT ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_FonteId") DO NOTHING;

-- ZEROS: municípios da malha sem nascido vivo registrado no ano (2019–2024)
-- Dado de EVENTO: ausência na tabulação estadual COMPLETA = 0 eventos no ano
-- (ver cabeçalho, "SEMÂNTICA DE ZERO × AUSÊNCIA"). A carga referenciada é a
-- da própria tabulação completa — é ELA que afirma o zero por omissão.
WITH carga AS (
  SELECT c."Carga_Id" id, c."Carga_FonteId" fonte_id FROM "Carga" c
  JOIN "Fonte" f ON f."Fonte_Id"=c."Carga_FonteId"
  WHERE f."Fonte_Nome"='SINASC/DATASUS — Nascidos vivos (TabNet, nvmt)' AND c."Carga_HashSha256"='bb76f145b8262d7d871c809bb966add4591dfa023dfd9d205fbb4385006fc8a9'
), ind AS (SELECT "Indicador_Id" id FROM "Indicador" WHERE "Indicador_Nome"='Nascidos vivos'),
anos(ano) AS (VALUES (2019),(2020),(2021),(2022),(2023),(2024))
INSERT INTO "Observacao" ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_Valor","Observacao_FonteId","Observacao_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(anos.ano,12,31), 0, carga.fonte_id, carga.id
FROM "Municipio" m
CROSS JOIN anos CROSS JOIN carga CROSS JOIN ind
WHERE NOT EXISTS (
  SELECT 1 FROM "Observacao" o
   WHERE o."Observacao_IndicadorId"=ind.id
     AND o."Observacao_CodigoIbge"=m."Municipio_CodigoIbge"
     AND o."Observacao_DataReferencia"=make_date(anos.ano,12,31))
ON CONFLICT ("Observacao_IndicadorId","Observacao_CodigoIbge","Observacao_DataReferencia","Observacao_FonteId") DO NOTHING;

-- Capítulo CID-10 × município (2019); linha cod6 NULL = estado (Total oficial)
