  WHERE f."Fonte_Nome"='SIM/DATASUS — Óbitos infantis (TabNet, inf10mt)' AND c."Carga_HashSha256"='fdaa1b47c28f46211c5ad7eafec87253773781b90b4aa7bbafd668e88aac7f77'
