INSERT INTO "ObservacaoCausa" ("ObservacaoCausa_IndicadorId","ObservacaoCausa_CodigoIbge","ObservacaoCausa_DataReferencia","ObservacaoCausa_Dimensao","ObservacaoCausa_Categoria","ObservacaoCausa_Valor","ObservacaoCausa_FonteId","ObservacaoCausa_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(d.ano,12,31), 'CAPITULO_CID10', d.categoria, d.valor, carga.fonte_id, carga.id
FROM dados d
LEFT JOIN "Municipio" m ON left(m."Municipio_CodigoIbge",6)=d.cod6
CROSS JOIN carga CROSS JOIN ind
WHERE d.cod6 IS NULL OR m."Municipio_CodigoIbge" IS NOT NULL
ON CONFLICT ON CONSTRAINT observacaocausa_unica DO NOTHING;

-- Componente etário × município (2019); linha cod6 NULL = estado
WITH carga AS (
  SELECT c."Carga_Id" id, c."Carga_FonteId" fonte_id FROM "Carga" c
  JOIN "Fonte" f ON f."Fonte_Id"=c."Carga_FonteId"
  WHERE f."Fonte_Nome"='SIM/DATASUS — Óbitos infantis (TabNet, inf10mt)' AND c."Carga_HashSha256"='a7dd9a7a26d674cecac3902e1ed5c5b36d83eb60fcc6a5fd3f197f92fcaec859'
), ind AS (SELECT "Indicador_Id" id FROM "Indicador" WHERE "Indicador_Nome"='Óbitos infantis'),
