INSERT INTO "ObservacaoCausa" ("ObservacaoCausa_IndicadorId","ObservacaoCausa_CodigoIbge","ObservacaoCausa_DataReferencia","ObservacaoCausa_Dimensao","ObservacaoCausa_Categoria","ObservacaoCausa_Valor","ObservacaoCausa_FonteId","ObservacaoCausa_CargaId")
SELECT ind.id, m."Municipio_CodigoIbge", make_date(d.ano,12,31), 'COMPONENTE', d.categoria, d.valor, carga.fonte_id, carga.id
FROM dados d
LEFT JOIN "Municipio" m ON left(m."Municipio_CodigoIbge",6)=d.cod6
CROSS JOIN carga CROSS JOIN ind
WHERE d.cod6 IS NULL OR m."Municipio_CodigoIbge" IS NOT NULL
ON CONFLICT ON CONSTRAINT observacaocausa_unica DO NOTHING;

